        patron = LocalizedText("""Santo patrón de La Salette-Fallavaux, Silang y Cavite""", """Patron saint of La Salette-Fallavaux, Silang, and Cavite""", """Novena a Nossa Senhora de La Salette"""),
        category = LocalizedText("""Novenas""", """Novenas""", """Novenas"""),
        description = LocalizedText("""Reza esta novena a Nuestra Señora de La Salette, que se apareció a dos jóvenes pastores en los Alpes franceses en 1846. Reza esta novena por La Salette-Fallavaux, Silang y Cavite.""", """Our Lady of La Salette appeared to two young shepherds in the French Alps in 1846. Pray this novena for La Salette-Fallavaux, Silang, and Cavite.""", """Santo padroeiro de La Salette-Fallavaux, Silang e Cavite"""),
